// Junta as duas entradas (formulário do n8n e painel) num formato só e valida.
const item = $input.first();
const ent = item.json;
const canal = ent.body && typeof ent.body === 'object' && !Array.isArray(ent.body) ? 'painel' : 'formulario';
const b = canal === 'painel' ? ent.body : ent;
const linha = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const EXTENSOES = ['pdf', 'docx', 'txt', 'md'];

const acao = canal === 'painel' ? (linha(b.acao).toLowerCase() || 'adicionar') : 'adicionar';
const documentoId = linha(b.documento_id);
const arquivoUrl = String(b.arquivo_url ?? '').trim();
let arquivoNome = linha(b.arquivo_nome);
if (canal === 'formulario') {
  const bin = item.binary || {};
  const chave = Object.keys(bin)[0];
  arquivoNome = chave ? linha(bin[chave].fileName) : '';
}
const extensao = ((arquivoNome.match(/\.([a-z0-9]+)$/i) || [])[1] || '').toLowerCase();
let titulo = linha(b.titulo ?? b['Título do documento']);
if (!titulo && acao === 'apagar' && documentoId) titulo = 'Documento #' + documentoId;

const erros = [];
if (acao !== 'adicionar' && acao !== 'apagar') erros.push('Ação inválida: use "adicionar" ou "apagar".');
if (acao === 'adicionar') {
  if (!titulo) erros.push('Informe o título do documento.');
  if (titulo.length > 200) erros.push('O título tem ' + titulo.length + ' caracteres; o limite é 200.');
  if (!EXTENSOES.includes(extensao)) erros.push('Formato não aceito' + (arquivoNome ? ' (' + arquivoNome + ')' : '') + '. Envie PDF, DOCX, TXT ou MD.');
  // Só baixa do Storage do Supabase, por link assinado: o webhook não busca endereços quaisquer.
  if (canal === 'painel' && !/^https:\/\/[a-z0-9-]+\.supabase\.co\/storage\/v1\/object\/sign\//i.test(arquivoUrl)) erros.push('Link do arquivo inválido.');
}
if (acao === 'apagar' && !/^(\d+|[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/i.test(documentoId)) erros.push('Informe o documento a apagar.');

return [{ json: {
  ok: erros.length === 0,
  erros,
  canal,
  acao,
  titulo,
  origem: linha(b.origem ?? b['Origem (opcional)']),
  enviado_por: canal === 'painel' ? linha(b.enviado_por) : 'Formulário do n8n',
  documento_id: documentoId,
  arquivo_url: arquivoUrl,
  arquivo_nome: arquivoNome,
  extensao,
} }];

// Prepara o arquivo para o leitor: uma chave só, com nome e tipo certos.
// O tipo vem da extensão, porque o Storage pode devolver application/octet-stream.
const pedido = $('Normalizar entrada').first().json;
const origem = pedido.canal === 'painel' ? $input.first().binary : $('Formulário: enviar documento').first().binary;
const chave = Object.keys(origem || {})[0];
if (!chave) return [{ json: { aceito: false, erro_envio: 'O arquivo não chegou ao n8n.' } }];
const TIPOS = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  txt: 'text/plain',
  md: 'text/plain',
};
const arquivo = { ...origem[chave], fileName: pedido.arquivo_nome || origem[chave].fileName, fileExtension: pedido.extensao, mimeType: TIPOS[pedido.extensao] };
return [{ json: { aceito: true }, binary: { arquivo } }];

// Resposta para o painel quando o envio nem chega a ser registrado.
const pedido = $('Normalizar entrada').first().json;
let http_status = 400;
let erros = pedido.erros || [];
if (pedido.ok) {
  const r = $input.first().json;
  http_status = 409;
  erros = ['Já existe um envio deste documento em processamento (envio #' + r.envio_em_andamento + '). Aguarde ele terminar.'];
}
return [{ json: { canal: pedido.canal, http_status, resposta: { ok: false, erros } } }];

// A saída do Postgres perde o arquivo: ele volta aqui, com os dados que o leitor põe no metadata.
const doc = $input.first().json;
return [{
  json: { documento_id: String(doc.documento_id), titulo: doc.titulo, versao: String(doc.nova_versao) },
  binary: $('Conferir arquivo').first().binary,
}];

// Junta os caminhos de erro (download, arquivo recusado, gravação, sem texto) numa mensagem só,
// com o que é preciso para desfazer a versão nova, se ela chegou a ser gravada.
const j = $input.first()?.json ?? {};
const e = j.error;
const detalhe = typeof e === 'string' ? e : (e && (e.message || e.description)) || '';
const motivo = j.erro_envio || ('Falha ao processar o arquivo' + (detalhe ? ': ' + detalhe : '.'));
const doc = $('Registrar documento').isExecuted ? $('Registrar documento').first().json : null;
return [{ json: {
  erro_envio: String(motivo).slice(0, 500),
  documento_id: doc ? String(doc.documento_id) : '',
  nova_versao: doc ? String(doc.nova_versao) : '',
  novo: doc ? doc.novo === true : false,
} }];
